function richEditor(block,index){return `<div class="gs-rich"><div class="gs-rich-toolbar" role="toolbar" aria-label="正文格式"><button type="button" data-rich-command="bold" data-rich-index="${index}" aria-label="加粗"><strong>B</strong></button><button type="button" data-rich-command="italic" data-rich-index="${index}" aria-label="斜体"><em>I</em></button><button type="button" data-rich-command="underline" data-rich-index="${index}" aria-label="下划线"><u>U</u></button><button type="button" data-rich-command="removeFormat" data-rich-index="${index}">清除格式</button></div><div contenteditable="${canEdit()?'true':'false'}" role="textbox" aria-multiline="true" aria-label="正文富文本编辑" data-rich-editor="${index}" class="gs-rich-editor">${M().richText(block.text||'')}</div></div>`}
function richValue(element){function visit(node){if(node.nodeType===3)return node.textContent;if(node.nodeType!==1)return '';const tag=node.tagName;if(['SCRIPT','STYLE','IFRAME','OBJECT'].includes(tag))return '';if(tag==='BR')return '\n';let value=[...node.childNodes].map(visit).join('');if(['B','STRONG'].includes(tag))value='**'+value+'**';else if(['I','EM'].includes(tag))value='*'+value+'*';else if(tag==='U')value='__'+value+'__';if(['DIV','P','LI'].includes(tag))value+='\n';return value}return [...element.childNodes].map(visit).join('').replace(/\n{3,}/g,'\n\n').replace(/\n$/,'')}
