function bindImages(host){host.querySelectorAll('[data-image-binding]').forEach(box=>{const binding=box.dataset.imageBinding,match=binding.match(/data-(block|item)-field-(\d+)/),sharedKey=binding.match(/data-shared-image="([^"]+)"/)?.[1],config=sharedKey&&!sharedKey.startsWith('body:')?'shared':binding.includes('portal-cover')?'portal':binding.includes('shortcut-cover')?'shortcut':null;const imageKey=sharedKey?'cover':config?'cover':'asset';const owner=()=>sharedKey?sharedImageOwner(sharedKey):match?(match[1]==='block'?bundle().record.blocks:bundle().record.items)[+match[2]]:config==='portal'?selectedPortal():selectedShortcut();const apply=value=>{if(config?!allowed('home.edit'):!canEdit())return false;if(!value&&config){const obj=owner();if(obj){if(config==='portal')delete obj.cover;else obj.cover=''}box.querySelector('[data-image-status]').textContent='已恢复默认或继承配图。';box.classList.remove('has-error');updatePreview();return true}const error=M().imageError(value);box.querySelector('[data-image-status]').textContent=error||'已更新图片。';box.classList.toggle('has-error',!!error);if(error){const obj=owner();if(obj)obj[imageKey]=value;updatePreview();return false}const obj=owner();if(!obj)return false;obj[imageKey]=value;const selection=box.parentElement.querySelector('select');if(selection)selection.value='';const frame=box.closest('.gs-image-fields')?.querySelector('img');if(frame)frame.src=M().assetSrc(value);updatePreview();return true};const registered=box.parentElement.querySelector('select');registered?.addEventListener('change',()=>{box.querySelector('[data-image-url]').value='';box.querySelector('[data-image-status]').textContent='已选择登记素材。';box.classList.remove('has-error')});box.querySelector('[data-image-url]').onchange=e=>apply(e.target.value.trim());box.querySelector('[data-image-file]').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const filenameError=M().moderationError(file.name);if(filenameError||!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>M().maxImageBytes){const obj=owner();if(obj)obj[imageKey]='invalid-upload';updatePreview();box.querySelector('[data-image-status]').textContent=filenameError||'请选择 2 MB 以内的 PNG、JPG、WebP 或 GIF 图片。';box.classList.add('has-error');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const result=M().registerImage(reader.result);box.querySelector('[data-image-status]').textContent=result.message;box.classList.toggle('has-error',!result.ok);if(result.ok)apply(reader.result);else{const obj=owner();if(obj)obj[imageKey]='invalid-upload';updatePreview()}};reader.onerror=()=>{box.querySelector('[data-image-status]').textContent='图片读取失败，请重选。'};reader.readAsDataURL(file)}})}
function homeCanvas(c){const p=selectedPortal(),t=p&&selectedTab(p),section=p&&M().sections(c).find(x=>x.id===p.sectionId),ids=t?(p.tabEntries?.[t.id]||section?.tabs.find(x=>x.id===t.id)?.entries.map(x=>x.recordId)||[]):[];return `<section class="gs-home-builder"><h4>首页区域</h4><p>词条与首页配置按百科独立保存。拖动栏目调整顺序，拖动词条加入当前栏目 / Tab。也可使用下方选择与上移、下移按钮。</p><div class="gs-home-canvas" data-home-drop="section">${c.portal.map((x,i)=>`<button type="button" draggable="${allowed('home.reorder')}" data-drag-section="${i}" data-drop-section="${i}" data-canvas-section="${E(x.sectionId)}" class="${p===x?'active':''}">☷ ${E(x.title)}</button>`).join('')||'<span>尚无栏目，请点击下方新建栏目。</span>'}</div>${t?`<h4>当前分类 · ${E(t.label)}</h4><div class="gs-home-canvas gs-entry-drop" data-home-drop="entry">${ids.map((id,i)=>`<button type="button" draggable="${allowed('home.reorder')}" data-drag-entry="${E(id)}" data-drop-entry="${i}">☷ ${E(portalLabel(id))}</button>`).join('')||'<span>将下方词条拖入此区域，或在「收录内容」勾选。</span>'}</div><details><summary>可拖入的词条</summary><div class="gs-drag-library">${M().list().map(r=>`<span tabindex="0" draggable="${allowed('home.edit')}" data-drag-record="${E(r.id)}">＋ ${E(r.title)}</span>`).join('')}</div></details>`:''}</section>`}
function bindHomeDrag(host){let drag=null;host.querySelectorAll('[data-drag-section],[data-drag-record],[data-drag-entry]').forEach(el=>el.ondragstart=e=>{drag=el.hasAttribute('data-drag-section')?{type:'section',value:Number(el.dataset.dragSection)}:{type:'entry',value:el.dataset.dragRecord||el.dataset.dragEntry};e.dataTransfer?.setData('text/plain',JSON.stringify(drag));if(e.dataTransfer)e.dataTransfer.effectAllowed='move'});host.querySelectorAll('[data-home-drop],[data-drop-section],[data-drop-entry]').forEach(el=>{el.ondragover=e=>{if(!drag)return;e.preventDefault();e.stopPropagation();el.classList.add('is-drag-over')};el.ondragleave=()=>el.classList.remove('is-drag-over');el.ondrop=e=>{e.preventDefault();e.stopPropagation();el.classList.remove('is-drag-over');if(!drag)return;const c=cfg();if(drag.type==='section'&&allowed('home.reorder')){const to=el.dataset.dropSection===undefined?c.portal.length-1:Number(el.dataset.dropSection),from=drag.value;if(to!==from){const [item]=c.portal.splice(from,1);c.portal.splice(to,0,item)}}else if(drag.type==='entry'&&allowed('home.edit')){const p=selectedPortal(),t=p&&selectedTab(p);if(!t)return;const section=M().sections(c).find(x=>x.id===p.sectionId);p.tabEntries=p.tabEntries||{};const ids=p.tabEntries[t.id]||section?.tabs.find(x=>x.id===t.id)?.entries.map(x=>x.recordId)||[],from=ids.indexOf(drag.value);if(from!==-1&&!allowed('home.reorder'))return;const next=ids.filter(id=>id!==drag.value),to=el.dataset.dropEntry===undefined?next.length:Number(el.dataset.dropEntry);next.splice(to,0,drag.value);p.tabEntries[t.id]=next}drag=null;paint()}});host.querySelectorAll('[data-canvas-section]').forEach(el=>el.onclick=()=>{state.configSection=el.dataset.canvasSection;paint()})}

