function clearHomeProperty(){state.homePropertySnapshot=null;state.homeEdit=null;state.itemSelection={};state.homeAdd=null;state.homeCategory=null;state.pendingHomeItem=null;state.homeEntryReturn=null;state.legacyBlockDraft=null;}
