function homeStartProperty(id,itemId){if(state.homePropertySnapshot?.id!==id)homeFinishProperty(false,false);const c=cfg(),p=c.portal.find(p=>p.sectionId===id);if(!state.homePropertySnapshot)state.homePropertySnapshot={id,value:clone(id==='legacy-shortcuts'?c.shortcuts:p)};state.homeEdit=id;state.configSection=id;state.itemSelection={};state.homeCategory=null;state.pendingHomeItem=null;state.legacyBlockDraft=id==='legacy-shortcuts'&&!itemId?clone(legacyBlock(c)):null;if(itemId){const key=id==='legacy-shortcuts'?'shortcut':'home',tabId=p?selectedTab(p)?.id:null,item=scopeItems(key,false).find(x=>x.id===itemId);state.itemSelection[key]=itemId;if(item)state.pendingHomeItem={key,sectionId:id,tabId,originalTabId:tabId,originalId:itemId,item:clone(item)};}}
