 targetInput?.addEventListener('input',()=>{const pending=state.pendingHomeItem;if(!pending)return;pending.query=targetInput.value;const exact=homeRecordMatch(targetInput.value);pending.item.targetId=exact?.id||'';host.querySelector('[data-hb-edit-entry]').disabled=!exact;if(state.notice?.code==='validation'){state.notice=null;host.querySelector('[data-studio-state="validation"]')?.remove();}suggest();});targetInput?.addEventListener('focus',suggest);targetInput?.addEventListener('blur',()=>{requestAnimationFrame(()=>{if(suggestions&&!suggestions.contains(document.activeElement)){suggestions.hidden=true;targetInput.setAttribute('aria-expanded','false');}});});
 targetInput?.addEventListener('keydown',event=>{if(event.key==='Escape'){suggestions.hidden=true;targetInput.setAttribute('aria-expanded','false');}if(['ArrowDown','Enter'].includes(event.key)&&!suggestions.hidden&&suggestions.querySelector('button')){event.preventDefault();if(event.key==='Enter')suggestions.querySelector('button').click();else suggestions.querySelector('button').focus();}});suggestions?.addEventListener('keydown',event=>{const buttons=[...suggestions.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();buttons[(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(event.key==='Escape'){suggestions.hidden=true;targetInput.focus();targetInput.setAttribute('aria-expanded','false');}});
