function workspaceConfig(c){const kind=state.workspaceTab||'sections',p=selectedPortal(),t=p&&selectedTab(p),panel=state.configPanel;let html='';if(kind==='schemas')return schemaConfigForm(c);if(kind==='tabs'||kind==='items'){html+=contextChoosers(kind);if(!p)return html+'<p class="gs-empty">暂无栏目，请先在栏目列表新增。</p>'}if(kind==='items')return html+sharedItemBuilder(homeItems(false),'home');if(panel){if(kind==='sections')return sectionFields(p);if(kind==='tabs')return html+tabFields(p,t);if(kind==='shortcuts')return sharedItemFields(selectedShortcut(),'shortcut')+`<label class="gs-check"><input type="checkbox" data-shortcut-visible ${selectedShortcut()?.visible!==false?'checked':''}>显示此金刚位</label>`}const values=kind==='sections'?c.portal:kind==='tabs'?portalTabs(p):c.shortcuts;const rows=values.map((x,i)=>({id:kind==='sections'?x.sectionId:x.id,title:kind==='tabs'?x.label:x.title||c.portal.find(p=>p.sectionId===x.targetId)?.title,note:kind==='sections'?`${portalTabs(x).length} 个 Tab · ${M().components().find(c=>c.id===layoutName(x.layout))?.label||x.layout}${x.visible===false?' · 已隐藏':''}`:kind==='tabs'?`${M().sections(c).find(s=>s.id===p.sectionId)?.tabs.find(t=>t.id===x.id)?.entries.length||0} 个内容项${x.visible===false?' · 已隐藏':''}`:`${x.targetType==='external'?'链接':x.targetType==='record'?'词条':'栏目'} · ${(x.targetType==='external'?x.url:'')||portalContent(x.targetId)?.title||c.portal.find(p=>p.sectionId===x.targetId)?.title||'未选择'}`,first:i===0,last:i===values.length-1}));return html+`<div class="gs-work-toolbar"><span>${rows.length} 项 · 可拖动排序</span><button class="gs-button" data-w-add="${kind}" ${!allowed('home.create')?'disabled':''}>＋ 新增${workspaceKind()}</button></div>`+workRows(rows,kind)+(kind==='sections'?componentLibrary('home'):'')}
